import type { TodayHeroData } from '@/lib/dashboard/today-hero'

// ─── Props ────────────────────────────────────────────────────────────────────

interface TodayHeroRowProps {
  data: TodayHeroData
  /** When true, renders values as muted skeletons (empty-state preview) */
  preview?: boolean
}

// ─── Shared tile primitives ───────────────────────────────────────────────────

function TileLabel({ children }: { children: React.ReactNode }) {
  return (
    <p
      className="text-[6.5px] font-bold uppercase tracking-[0.12em] text-[var(--color-muted-foreground)]"
      aria-hidden="true"
    >
      {children}
    </p>
  )
}

function TileValue({
  children,
  muted = false,
  className,
}: {
  children: React.ReactNode
  muted?: boolean
  className?: string
}) {
  return (
    <p
      className={cn(
        'font-serif text-[22px] italic leading-tight tabular-nums',
        muted ? 'text-[var(--color-muted-foreground)]' : 'text-[var(--color-foreground)]',
        className,
      )}
    >
      {children}
    </p>
  )
}

function TileSubtext({ children }: { children: React.ReactNode }) {
  return (
    <p className="mt-0.5 text-[11px] leading-snug text-[var(--color-muted-foreground)]">
      {children}
    </p>
  )
}

function DeltaPill({
  value,
  positive,
  muted = false,
}: {
  value: string
  positive: boolean
  muted?: boolean
}) {
  if (muted) {
    return (
      <span className="rounded-full bg-[var(--color-muted)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--color-muted-foreground)]">
        {value}
      </span>
    )
  }
  return (
    <span
      className={cn(
        'rounded-full px-1.5 py-0.5 text-[10px] font-medium',
        positive
          ? 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]'
          : 'bg-[rgba(178,58,43,0.08)] text-[var(--color-rust)]',
      )}
    >
      {value}
    </span>
  )
}

