/** Tile 1 — Revenue today (HERO tile, Onyx bg) */
function RevenueTile({
  data,
  preview,
}: {
  data: TodayHeroData
  preview: boolean
}) {
  const collected = formatCurrency(data.revenueToday)
  const expected = formatCurrency(data.revenueExpected)
  const delta = data.revenueVsYesterday
  const deltaLabel =
