        'group relative flex flex-col justify-between rounded-xl p-4 transition-all duration-150',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)] focus-visible:ring-offset-2',
        preview
          ? 'cursor-default bg-[var(--color-muted)] border border-[var(--color-border)]'
