}

export function OverdueAlertBanner({ item }: OverdueAlertBannerProps) {
  const [dismissed, setDismissed] = useState(false)
  const [pending, startTransition] = useTransition()

  if (dismissed) return null

  function handleSendReminder() {
    startTransition(async () => {
      const result = await sendDepositReminderAction(item.bookingId)
      if (result.ok) {
        toast.success('Reminder sent.')
        setDismissed(true)
      } else {
        toast.error(result.error ?? 'Failed to send reminder.')
      }
    })
  }

  return (
    <div
      role="alert"
      aria-live="polite"
      className={cn(
        'flex items-start gap-3 rounded-xl border border-[rgba(178,58,43,0.25)] bg-[rgba(178,58,43,0.06)] px-4 py-3',
      )}
    >
      <AlertTriangle
        className="mt-0.5 h-4 w-4 shrink-0 text-[var(--color-rust)]"
        aria-hidden="true"
      />
      <div className="flex-1 min-w-0">
        <p className="text-[13px] font-semibold text-[var(--color-onyx)]">
          {item.clientName}
          <span className="ml-1 font-normal text-[var(--color-muted-foreground)]">
