          </span>
        </p>
      </div>
      <div className="flex shrink-0 items-center gap-2">
        <button
          type="button"
          onClick={handleSendReminder}
          disabled={pending}
          className={cn(
            'rounded-lg bg-[var(--color-rust)] px-2.5 py-1 text-[12px] font-medium text-[var(--color-bone)] transition-opacity',
            'hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)] focus-visible:ring-offset-2',
            pending && 'cursor-wait opacity-60',
          )}
          aria-busy={pending}
        >
          {pending ? 'Sending…' : 'Send reminder'}
        </button>
        <button
          type="button"
          onClick={() => setDismissed(true)}
          className="rounded-md p-1 text-[var(--color-muted-foreground)] transition-colors hover:text-[var(--color-foreground)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]"
          aria-label="Dismiss alert"
        >
          <X className="h-3.5 w-3.5" aria-hidden="true" />
        </button>
      </div>
    </div>
  )
}

