// ─── Global keyboard handler hook ─────────────────────────────────────────────

export function useGlobalShortcuts() {
  const router = useRouter()
  const [shortcutsOpen, setShortcutsOpen] = useState(false)
  const [paletteOpen, setPaletteOpen] = useState(false)
  const gPressedRef = useRef(false)
  const gTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    function handler(e: KeyboardEvent) {
      const target = e.target as HTMLElement
      const tag = target.tagName
      const inInput =
        tag === 'INPUT' ||
        tag === 'TEXTAREA' ||
        tag === 'SELECT' ||
        target.isContentEditable

      // ⌘K / Ctrl+K — command palette
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setPaletteOpen((prev) => !prev)
        return
      }

      // Escape — close modals
      if (e.key === 'Escape') {
        setShortcutsOpen(false)
        setPaletteOpen(false)
        return
      }

      if (inInput) return

      // ? — shortcut overlay
      if (e.key === '?') {
        e.preventDefault()
        setShortcutsOpen((prev) => !prev)
        return
      }

      // G then I/C/P — vim-style navigation
      if (e.key === 'g' || e.key === 'G') {
        e.preventDefault()
        gPressedRef.current = true
        if (gTimerRef.current) clearTimeout(gTimerRef.current)
        gTimerRef.current = setTimeout(() => {
          gPressedRef.current = false
        }, 1500)
        return
      }

      if (gPressedRef.current) {
        gPressedRef.current = false
        if (gTimerRef.current) clearTimeout(gTimerRef.current)
        const key = e.key.toLowerCase()
        if (key === 'i') { e.preventDefault(); router.push('/inbox'); return }
        if (key === 'c') { e.preventDefault(); router.push('/calendar'); return }
        if (key === 'p') { e.preventDefault(); router.push('/payments'); return }
        return
      }

      // N — new appointment
      if (e.key === 'n' || e.key === 'N') {
        e.preventDefault()
        router.push('/appointments/new')
        return
      }

      // C — add client
      if (e.key === 'c' || e.key === 'C') {
        e.preventDefault()
        router.push('/clients?new=1')
        return
      }

      // D — take deposit
      if (e.key === 'd' || e.key === 'D') {
        e.preventDefault()
        router.push('/payments/new')
        return
      }

      // F — send consent (navigate to forms)
      if (e.key === 'f' || e.key === 'F') {
        e.preventDefault()
        router.push('/forms')
        return
      }
    }

    window.addEventListener('keydown', handler)
    return () => {
      window.removeEventListener('keydown', handler)
      if (gTimerRef.current) clearTimeout(gTimerRef.current)
    }
  }, [router])

  return {
    shortcutsOpen,
    setShortcutsOpen,
    paletteOpen,
    setPaletteOpen,
  }
}

// ─── Composed export ──────────────────────────────────────────────────────────

export function ShortcutOverlay() {
  const { shortcutsOpen, setShortcutsOpen, paletteOpen, setPaletteOpen } =
    useGlobalShortcuts()

  return (
    <>
      <ShortcutModal
        open={shortcutsOpen}
        onClose={() => setShortcutsOpen(false)}
      />
      <CommandPalette
        open={paletteOpen}
        onClose={() => setPaletteOpen(false)}
      />
    </>
  )
}

