'use client'

import { useEffect, useState } from 'react'
import { ActivityFeed } from '@/components/shared/ActivityFeed'
import { AlertsCard } from '@/components/shared/AlertsCard'
import { InventoryAlertsCard } from '@/components/inventory/InventoryAlertsCard'
import { GettingStartedCard } from '@/components/dashboard/GettingStartedCard'
import { TodayAgendaWidget } from '@/components/dashboard/TodayAgendaWidget'
import { QuickActionsRow } from '@/components/dashboard/QuickActionsRow'
import { EmptyDashboardState } from '@/components/dashboard/EmptyDashboardState'
import { useTodayAgenda } from '@/hooks/dashboard/use-today-agenda'
import { useRecentActivity } from '@/hooks/dashboard/use-recent-activity'
import { useInventoryAlerts } from '@/hooks/dashboard/use-inventory-alerts'
import { useDashboardAlerts } from '@/hooks/dashboard/use-dashboard-alerts'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'
import { RoleAwareHero } from './RoleAwareHero'
import { TodayQuickActionsRow } from './QuickActionsRow'
import { TodayHeroRow } from './TodayHeroRow'
import { OverdueAlertBanner } from './OverdueAlertBanner'
import { ShortcutOverlay } from './ShortcutOverlay'
import type { TodayHeroData, UrgentOverdueItem } from '@/lib/dashboard/today-hero'
import type { Database } from '@/lib/supabase/types'

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

interface TodayClientProps {
  firstName: string
  studioName: string
  hasStudio: boolean
  studioId: string | null
  role: StudioRole
  ownArtistId?: string | null | undefined
  artistEarningsToday?: number | undefined
  gettingStartedCounts: GettingStartedCounts
  /** Pre-fetched from server — hero KPI data for today */
  heroData: TodayHeroData | null
  /** Pre-fetched from server — most urgent overdue deposit item (if any) */
  urgentOverdueItem: UrgentOverdueItem | null
}

// ─── Greeting ─────────────────────────────────────────────────────────────────

function buildGreeting(firstName: string, studioTimezone: string | null): string {
  const tz = studioTimezone ?? Intl.DateTimeFormat().resolvedOptions().timeZone
  const nowInTz = new Date().toLocaleString('en-US', { timeZone: tz, hour: 'numeric', hour12: false })
  const hour = parseInt(nowInTz.split(':')[0] ?? '12', 10)
  if (hour < 12) return `Good morning, ${firstName}.`
  if (hour < 17) return `Good afternoon, ${firstName}.`
  return `Good evening, ${firstName}.`
}

function formatContextSummary(hero: TodayHeroData, studioTimezone: string | null): string {
  const formatCents = (c: number) =>
    `$${(c / 100).toLocaleString('en-US', { maximumFractionDigits: 0 })}`

  const parts: string[] = []
  if (hero.bookingsToday > 0) {
    parts.push(`${hero.bookingsToday} session${hero.bookingsToday !== 1 ? 's' : ''} today`)
  }
  if (hero.revenueExpected > 0) {
    parts.push(`${formatCents(hero.revenueExpected)} expected`)
  }
  if (hero.depositsPendingCount > 0) {
    parts.push(`${hero.depositsPendingCount} overdue deposit${hero.depositsPendingCount !== 1 ? 's' : ''}`)
  }
  void studioTimezone // consumed by buildGreeting above
  return parts.join(' · ')
}

function formatDate(): string {
  return new Date().toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  })
}

// ─── Main component ───────────────────────────────────────────────────────────

export function TodayClient({
  firstName,
  studioName,
  hasStudio,
  studioId,
  role,
  ownArtistId,
  artistEarningsToday = 0,
  gettingStartedCounts,
  heroData,
  urgentOverdueItem,
}: TodayClientProps) {
  const agendaQuery = useTodayAgenda(hasStudio)
  const activityQuery = useRecentActivity(hasStudio)
  const inventoryAlertsQuery = useInventoryAlerts(hasStudio)
  const alertsQuery = useDashboardAlerts(hasStudio)

  const [dismissedIds, setDismissedIds] = useState<string[]>([])

  const [checklistDismissed, setChecklistDismissed] = useState(false)
  useEffect(() => {
    setChecklistDismissed(
      localStorage.getItem('inkos:getting-started:dismissed') === '1',
    )
  }, [])

  const visibleAlerts = (alertsQuery.data ?? []).filter(
    (a) => !dismissedIds.includes(a.id),
  )

  const showEmptyState =
    checklistDismissed && gettingStartedCounts.bookings === 0

  const agendaAppointments = agendaQuery.data ?? []
  const totalToday = agendaAppointments.length

  const showKpis = role === 'owner' || role === 'admin'

  // Greeting with live context from server-fetched heroData
  const greetingText = buildGreeting(firstName, null)
  const contextSummary = heroData ? formatContextSummary(heroData, null) : null

  return (
    <div className="min-h-full bg-[var(--color-page-bg)]">
      {/* Global keyboard shortcuts + command palette */}
      <ShortcutOverlay />

      <div className="mx-auto max-w-[1440px] space-y-6 px-4 pb-10 pt-6 sm:px-6 lg:px-8">

        {/* ── Header ── */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <p className="mb-1 text-[11px] font-bold uppercase tracking-[0.08em] text-stone-brand">
              {studioName}
            </p>
            <h1 className="font-display text-[52px] leading-[1.05] text-foreground">
              The studio,{' '}
              <span className="font-serif-italic text-rust">at a glance.</span>
            </h1>
            <p className="mt-2 text-sm text-[var(--color-muted-foreground)]">
              {formatDate()} · {greetingText}
              {contextSummary && (
                <span className="ml-1 font-medium text-[var(--color-foreground)]">
                  {contextSummary}
                </span>
              )}
            </p>
          </div>
        </div>

        {/* ── Overdue alert banner (conditional — only when overdue > 0) ── */}
        {urgentOverdueItem && (
          <OverdueAlertBanner item={urgentOverdueItem} />
        )}

        {/* ── Hero KPI Row (5 tiles, today-scoped) ── */}
        {showKpis && heroData && (
          <TodayHeroRow data={heroData} />
        )}

        {/* ── Today quick actions (card grid with descriptions) ── */}
        <TodayQuickActionsRow />

        {/* ── Legacy quick actions toolbar (shortcut buttons) ── */}
        <QuickActionsRow />

        {/* ── Getting started checklist ── */}
        <GettingStartedCard counts={gettingStartedCounts} />

        {showEmptyState ? (
          <EmptyDashboardState />
        ) : (
          <>
            {/* ── Role-aware hero: TodayQueue + role-specific widgets ── */}
            {hasStudio && studioId && (
              <RoleAwareHero
                role={role}
                studioId={studioId}
                ownArtistId={ownArtistId}
                artistEarningsToday={artistEarningsToday}
                inventoryAlerts={inventoryAlertsQuery.data}
              />
            )}

            {/* WAVE 2 SLOT: Next Up widget */}
            {/* WAVE 2 SLOT: Today's Schedule Timeline */}
            {/* WAVE 2 SLOT: Revenue trajectory + Artist utilization */}
            {/* WAVE 2 SLOT: Pending deposits + Consent status + Inventory + Guest residency */}

            {/* ── Agenda + Activity ── */}
            <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
              <div id="today-agenda" className="lg:col-span-8">
                <TodayAgendaWidget
                  appointments={agendaAppointments}
                  totalToday={totalToday}
                  loading={agendaQuery.isLoading}
                />
              </div>
              <div className="lg:col-span-4">
                <ActivityFeed
                  events={activityQuery.data ?? []}
                  loading={activityQuery.isLoading}
                  {...(studioId !== null ? { studioId } : {})}
                />
              </div>
            </div>

            {/* ── Alerts ── */}
            <div className="grid grid-cols-1 gap-4">
              <AlertsCard
                alerts={visibleAlerts}
                loading={alertsQuery.isLoading}
                onDismiss={(id) =>
                  setDismissedIds((prev) => [...prev, id])
                }
              />
              {inventoryAlertsQuery.data != null && (
                <InventoryAlertsCard
                  openAlertsCount={inventoryAlertsQuery.data.open_alerts_count}
                  itemsBelowThreshold={inventoryAlertsQuery.data.items_below_threshold}
                  loading={inventoryAlertsQuery.isLoading}
                />
              )}
            </div>
          </>
        )}

      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { TodayClient } from '@/components/today/TodayClient'
import { ArtistTodayDashboard } from '@/components/today/ArtistTodayDashboard'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'
import { getArtistIdForUser, getArtistEarningsToday } from '@/lib/today/queries'
import { getTodayHeroData, getMostUrgentOverdueItem } from '@/lib/dashboard/today-hero'
import { logger } from '@/lib/logger'
import type { Database } from '@/lib/supabase/types'

export const metadata: Metadata = {
  title: 'Today — InkOS',
}

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

export default async function TodayPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const [profileResult, memberResult] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name')
      .eq('id', user.id)
      .single(),
    supabase
      .from('studio_members')
      .select('studio_id, role, studios(name, timezone)')
      .eq('user_id', user.id)
      .is('deactivated_at', null)
      .order('created_at', { ascending: true })
      .limit(1)
      .single(),
  ])

  const firstName = profileResult.data?.full_name?.split(' ')[0] ?? 'there'
  const studioData = memberResult.data?.studios as { name: string; timezone: string } | null
  const studioName = studioData?.name ?? 'My Studio'
  const studioTimezone = studioData?.timezone ?? 'America/New_York'
  const hasStudio = !!memberResult.data?.studio_id
  const studioId = memberResult.data?.studio_id
  const role: StudioRole = memberResult.data?.role ?? 'owner'

  let gettingStartedCounts: GettingStartedCounts = {
    services: 0,
    artists: 0,
    schedules: 0,
    bookings: 0,
    bookingPageConfigured: false,
  }

  let ownArtistId: string | null = null
  let artistEarningsToday = 0

  if (studioId) {
    const [servicesRes, artistsRes, schedulesRes, bookingsRes, bpRes] = await Promise.all([
      supabase
        .from('services')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('artists')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('artist_schedules')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('booking_page_settings')
        .select('studio_id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
    ])

    gettingStartedCounts = {
      services: servicesRes.count ?? 0,
      artists: artistsRes.count ?? 0,
      schedules: schedulesRes.count ?? 0,
      bookings: bookingsRes.count ?? 0,
      bookingPageConfigured: (bpRes.count ?? 0) > 0,
    }

    if (role === 'artist' || role === 'guest_artist') {
      ownArtistId = await getArtistIdForUser(supabase, studioId, user.id)
      if (ownArtistId) {
        artistEarningsToday = await getArtistEarningsToday(supabase, studioId, ownArtistId)
      }
    }
  }

  // S19: artist and guest_artist roles see their personal dashboard
  if ((role === 'artist' || role === 'guest_artist') && studioId && ownArtistId) {
    return (
      <ArtistTodayDashboard
        firstName={firstName}
        studioId={studioId}
        artistId={ownArtistId}
        artistEarningsToday={artistEarningsToday}
      />
    )
  }

  // ── Hero KPI data (owner/admin only) ────────────────────────────────────────
  let heroData = null
  let urgentOverdueItem = null

  if (studioId && (role === 'owner' || role === 'admin')) {
    try {
      ;[heroData, urgentOverdueItem] = await Promise.all([
        getTodayHeroData(supabase, studioId, studioTimezone),
        getMostUrgentOverdueItem(supabase, studioId, studioTimezone),
      ])
    } catch (err) {
      logger.error({ err, studioId }, 'dashboard: failed to fetch hero data')
      // Non-fatal — TodayClient renders without hero data
    }
  }

  return (
    <TodayClient
      firstName={firstName}
      studioName={studioName}
      hasStudio={hasStudio}
      studioId={studioId ?? null}
      role={role}
      ownArtistId={ownArtistId}
      artistEarningsToday={artistEarningsToday}
      gettingStartedCounts={gettingStartedCounts}
      heroData={heroData}
      urgentOverdueItem={urgentOverdueItem}
    />
  )
}

