// ─── Types ────────────────────────────────────────────────────

type ActionResult<T = undefined> =
  | { ok: true; data?: T; error?: never }
  | { ok: false; error: string; data?: never }

interface BatchItem {
  kind: InboxItemKind
  id: string
}

/** Subset of InboxItemKind that inbox_assignments supports (excludes 'unread-message') */
type DBInboxItemKind = 'deposit' | 'form' | 'waitlist' | 'client'

function isDBInboxKind(kind: InboxItemKind): kind is DBInboxItemKind {
  return kind === 'deposit' || kind === 'form' || kind === 'waitlist' || kind === 'client'
}

